edits.newText:
test('rejects values outside the inclusive Count bounds', () => {
  assert.equal(permit(-1), false);
  assert.equal(permit(4), false);
});

test('rejects malformed non-Count inputs without coercion', () => {
  for (const value of ['1', null, undefined, NaN, Infinity, -Infinity, 1.5]) {
    assert.equal(permit(value), false, `permit(${String(value)})`);
  }
});

